Here is the full nav typography and CSS spec from `components/Nav.tsx` and `app/globals.css`, with token values resolved so you can replicate it elsewhere.

---

## Font setup (required)

The nav depends on **Garet** (brand) and **JetBrains Mono** (mobile menu toggle only).

```9:29:app/globals.css
@font-face {
  font-family: 'Garet';
  font-weight: 400;
  font-style: normal;
  font-display: swap;
  src: url('/fonts/Garet-Book.woff2') format('woff2'),
       url('/fonts/Garet-Book.woff') format('woff'),
       url('/fonts/Garet-Book.ttf') format('truetype'),
       url('/fonts/Garet-Book.otf') format('opentype');
}
@font-face {
  font-family: 'Garet';
  font-weight: 500 800;
  font-style: normal;
  font-display: swap;
  src: url('/fonts/Garet-Heavy.woff2') format('woff2'),
       url('/fonts/Garet-Heavy.woff') format('woff'),
       url('/fonts/Garet-Heavy.ttf') format('truetype'),
       url('/fonts/Garet-Heavy.otf') format('opentype');
}
```

```7:7:app/globals.css
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500&display=swap');
```

**Token definitions:**

| Token | Resolved value |
|---|---|
| `--font-body` | `'Garet', system-ui, -apple-system, BlinkMacSystemFont, sans-serif` |
| `--font-mono` | `'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace` |
| `--ink` | `#0A0A0A` |
| `--ink-soft` | `#1F1F1F` |
| `--paper` | `#FAFAF7` |
| `--paper-pure` | `#FFFFFF` |
| `--mute-1` | `#E8E8E4` |
| `--ease` | `cubic-bezier(.2, 0, 0, 1)` |
| `--dur-fast` | `80ms` |
| `--shadow-elev` | `0 1px 2px rgba(10,10,10,.06), 0 4px 16px rgba(10,10,10,.04)` |

**Important:** Nav links use `font-weight: 500`, which maps to the **Garet Heavy** file (`font-weight: 500 800` range), not Garet Book.

**Inherited from `html, body`** (applies to nav text unless overridden):

```258:267:app/globals.css
html, body {
  margin: 0;
  padding: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: var(--fs-base);
  line-height: var(--lh-normal);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
```

(`--fs-base` = `16px`, `--lh-normal` = `1.45`)

---

## Desktop nav links (`nav.primary a`)

```1324:1326:app/globals.css
nav.primary { display: flex; gap: 28px; }
nav.primary a { font-family: var(--font-body); font-weight: 500; font-size: 13px; color: var(--ink); text-decoration: none; }
nav.primary a:hover { text-decoration: underline; text-underline-offset: 6px; text-decoration-thickness: 2px; }
```

| Property | Value |
|---|---|
| `font-family` | `'Garet', system-ui, -apple-system, BlinkMacSystemFont, sans-serif` |
| `font-weight` | `500` (Garet Heavy) |
| `font-size` | `13px` |
| `color` | `#0A0A0A` |
| `text-decoration` | `none` |
| `letter-spacing` | not set (inherits `0` / normal) |
| `line-height` | not set (inherits `1.45` from body) |
| `text-transform` | not set (normal) |

**Hover:**

| Property | Value |
|---|---|
| `text-decoration` | `underline` |
| `text-underline-offset` | `6px` |
| `text-decoration-thickness` | `2px` |

**Layout:** `display: flex; gap: 28px` on the `<nav>`.

**Breakpoint:** Hidden at `max-width: 920px`:

```2336:2336:app/globals.css
  nav.primary { display: none; }
```

---

## Mobile drawer nav links (`.hdr-mobile-drawer__nav a`)

```1436:1452:app/globals.css
.hdr-mobile-drawer__nav a {
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 15px;
  line-height: 1.3;
  padding: 14px 10px;
  text-decoration: none;
  color: var(--ink);
  border-bottom: 1px solid var(--mute-1);
}
.hdr-mobile-drawer__nav a:last-child {
  border-bottom: none;
}
.hdr-mobile-drawer__nav a:hover {
  text-decoration: underline;
  text-underline-offset: 5px;
  text-decoration-thickness: 2px;
}
```

| Property | Value |
|---|---|
| `font-family` | Garet stack (same as desktop) |
| `font-weight` | `500` |
| `font-size` | `15px` |
| `line-height` | `1.3` |
| `padding` | `14px 10px` |
| `color` | `#0A0A0A` |
| `text-decoration` | `none` |
| `border-bottom` | `1px solid #E8E8E4` (last child: none) |

**Hover:** underline, `text-underline-offset: 5px`, `text-decoration-thickness: 2px`.

---

## Mobile menu toggle (`.hdr-menu-toggle`) — different font

```1336:1349:app/globals.css

/**
 * Tower CT Ant shell — product face.
 * Operator / modeling: Consultant ▾ | Operator | Contact ▾. No leftover firm chip.
 * Consultant person: Consultant only. Contact person (/c/<token>): no this switcher.
 */
import { useEffect, useMemo, useState, type CSSProperties, type ReactNode } from "react";
import {
  App,
  Button,
  ConfigProvider,
  Dropdown,
  Empty,
  Layout,
  Space,
  Switch,
  Typography,
  theme as antTheme,
} from "antd";
import {
  BankOutlined,
  BulbOutlined,
  DownOutlined,
  LinkOutlined,
  LogoutOutlined,
  TeamOutlined,
  UserOutlined,
} from "@ant-design/icons";
import "./antFill.css";
import { useAuth } from "../../auth/AuthContext";
import { isAuthDisabled } from "../../auth/authClient";
import { isPlatformAdminEmail } from "../../auth/platformAdmin";
import { buildTowerAntTheme, loadAntThemeMode, saveAntThemeMode, type AntThemeMode } from "./theme";
import { ConsultantAntScene } from "./consultant/ConsultantAntScene";
import { OperatorAntScene } from "./operator/OperatorAntScene";
import { ContactAntScene, ContactWorkspace } from "./contact/ContactWorkspace";
import { LoginModule } from "./consultant/LoginModule";
import { ViewAsProvider, useViewAs } from "./viewAsContext";

const { Header, Content } = Layout;
const { Text } = Typography;

type AntDesk = "consultant" | "operator" | "contact";

function contactTokenFromPath(): string | null {
  if (typeof window === "undefined") return null;
  const match = window.location.pathname.match(/^\/c\/([^/]+)/);
  return match ? decodeURIComponent(match[1]) : null;
}

function Slot({
  active,
  children,
  onClick,
}: {
  active: boolean;
  children: ReactNode;
  onClick?: () => void;
}) {
  const { token } = antTheme.useToken();
  const style: CSSProperties = {
    appearance: "none",
    border: "none",
    background: active ? token.colorBgContainer : "transparent",
    boxShadow: active ? token.boxShadowTertiary : undefined,
    borderRadius: token.borderRadiusSM,
    padding: "4px 11px",
    cursor: "pointer",
    fontWeight: 500,
    color: token.colorText,
    display: "inline-flex",
    alignItems: "center",
    gap: 6,
    lineHeight: "22px",
  };
  return (
    <button type="button" style={style} onClick={onClick}>
      {children}
    </button>
  );
}

export function PrototypeAntApp() {
  const [mode, setMode] = useState<AntThemeMode>(() => loadAntThemeMode());
  const themeConfig = useMemo(() => buildTowerAntTheme(mode), [mode]);
  const seatToken = contactTokenFromPath();

  if (seatToken) {
    return (
      <ConfigProvider theme={themeConfig}>
        <App style={{ height: "100%" }}>
          <ContactWorkspace token={seatToken} />
        </App>
      </ConfigProvider>
    );
  }

  return (
    <ConfigProvider theme={themeConfig}>
      <App style={{ height: "100%" }}>
        <ViewAsProvider>
          <AntShell
            mode={mode}
            onMode={(m) => {
              setMode(m);
              saveAntThemeMode(m);
            }}
          />
        </ViewAsProvider>
      </App>
    </ConfigProvider>
  );
}

function AntShell({
  mode,
  onMode,
}: {
  mode: AntThemeMode;
  onMode: (m: AntThemeMode) => void;
}) {

